    n, k = map(int, input().split())
    s = input()

    operations = []
    i = 0
    while i < n:
        count = 0
        for j in range(i, n):
            if s[j] == 'A':
                count += 1
            else:
                count -= 1
            if count < 0:
                operations.append((i+1, 'B'))
                count = 0
                i += 1
                break

    if k > count:
        operations.append((1, 'B'))
        k -= 1

    operations.sort(key=lambda x: x[0])
    ans = []
    for i in range(len(operations)):
        if k == 0:
            break
        if operations[i][1] == 'A':
            k -= 1
            ans.append((operations[i][0], 'A'))
        else:
            k -= 1
            ans.append((operations[i][0], 'B'))

    print(len(operations))
    for i in range(len(ans)):
        print(ans[i][0], ans[i][1])

