def solve(x, y, k):
    queue = [(0, x, y, 0)]
    visited = set()
    while queue:
        time, curr, prev, dist = heapq.heappop(queue)
        if (curr, prev) in visited:
            continue
        visited.add((curr, prev))
        if curr == y:
            return dist
        if curr == x:
            return dist + k
        if curr + 1 <= x and (curr + 1, prev) not in visited:
            heapq.heappush(queue, (time + 1, curr + 1, (curr + 1, curr), dist + 1))
        if curr - 1 >= 0 and (curr - 1, prev) not in visited:
            heapq.heappush(queue, (time + 1, curr - 1, (curr - 1, curr), dist + 1))

