import sys

def solve():
    n = int(input())
    arr = list(map(int, input().split()))

    def binary_search(arr, target):
        left, right = 0, n - 1
        while left < right:
            mid = (left + right) // 2
            if arr[mid] < target:
                left = mid + 1
            else:
                right = mid
        return left + 1

    def binary_search_right(arr, target):
        left, right = 0, n - 1
        while left < right:
            mid = (left + right) // 2
            if arr[mid] > target:
                right = mid
            else:
                left = mid + 1
        return right + 1

    def binary_search_left(arr, target):
        left, right = 0, n - 1
        while left < right:
            mid = (left + right) // 2
            if arr[mid] > target:
                right = mid
            else:
                left = mid + 1
        return left

    def binary_search_right2(arr, target):
        left, right = 0, n - 1
        while left < right:
            mid = (left + right) // 2
            if arr[mid] > target:
                right = mid
            else:
                left = mid + 1
        return right

    min_operations = float('inf')
    for i in range(n):
        left = 0
        right = i
        while left < right:
            mid = (left + right) // 2
            if arr[mid] <= arr[i]:
                left = mid + 1
            else:
                right = mid
        min_operations = min(min_operations, binary_search(arr, arr[i] + 1) - i)

    for i in range(n - 1, -1, -1):
        left = 0
        right = i
        while left < right:
            mid = (left + right) // 2
            if arr[mid] >= arr[i]:
                left = mid + 1
            else:
                right = mid
        min_operations = min(min_operations, binary_search_right(arr, arr[i] + 1) - i)

    print(min_operations)

