def solve(n):
    def permute(arr, n):
        if n == 1:
            return [arr]
        res = []
        for i in range(n):
            for j in range(i + 1, n):
                arr[i], arr[j] = arr[j], arr[i]
                res.append(arr)
        return res

    def is_valid(arr):
        for i in range(1, len(arr)):
            if arr[i] == arr[i - 1]:
                return False
        return True

    def backtrack(start, path, n):
        if len(path) == n:
            if is_valid(path):
                count = 0
                for i in range(1, n + 1):
                    if i in path:
                        count += 1
                return count
        for i in range(start, n + 1):
            path.append(i)
            backtrack(i + 1, path, n)
            path.pop()

    for _ in range(int(input())):
        n = int(input())
        arr = list(map(int, input().split()))
        res = permute(arr, n)
        count = backtrack(1, [], n)
